export async function getSchedule(sport: string, forceRefresh = false): Promise<Game[]> {
  const cacheKey = sport.toLowerCase();
  const cached = scheduleCache[cacheKey];

  if (!forceRefresh && cached && (Date.now() - cached.timestamp < CACHE_DURATION)) {
    return cached.data;
  }

  return callWithRetry(async () => {
    const ai = getAI();
    const result = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Find ALL currently scheduled or live ${sport} games for today and this week.
      IMPORTANT:
      1. If games are LIVE, include the current score (e.g., "24-17").
      2. If games are SCHEDULED, include the time.
      3. Include MONEYLINE, SPREAD, and TOTAL odds if available.
      4. Flag "isMustWin" as true if a team is facing elimination or fighting for a playoff spot.
      RETURN JSON ONLY.`,
      config: {
        responseMimeType: 'application/json',
        responseSchema: scheduleSchema,
        tools: [{ googleSearch: {} }]
      }
    });

    const text = result.text;
    if (!text) return [];

    const data = JSON.parse(text);
    const games = data.games || [];

    scheduleCache[cacheKey] = { data: games, timestamp: Date.now() };
    return games;
  });
}

export async function generatePrediction(homeTeam: string, awayTeam: string, systemInstruction: string): Promise<Prediction> {
    return callWithRetry(async () => {
        const ai = getAI();
        const result = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: `Analyze ${homeTeam} vs ${awayTeam} with maximum forensic depth.

            OBJECTIVE: Provide the single HIGHEST POSSIBILITY outcome based on granular data.

            REQUIRED DATA POINTS TO ANALYZE:
            1. **Officials Analysis**: Who is the referee? What is their home/road bias? Impact on Over/Under?
            2. **Venue Intelligence**: Altitude? Weather? Crowd noise decibels? Court/Field surface quirks?
            3. **Simulation**: Run 10,000 internal simulations. What is the win % distribution?
            4. **Veto Phase**: Are there any late scratches or "flu game" rumors?
            5. **Syndicate Money**: Where is the sharp money moving the line?

            Provide a strict "Best Bet" with edge percentage.
            Return JSON matching the schema.`,
            config: {
                systemInstruction: systemInstruction,
                responseMimeType: 'application/json',
                responseSchema: predictionSchema,
                tools: [{ googleSearch: {} }],
                thinkingConfig: { thinkingBudget: 32768 }
            }
        });

        const text = result.text;
        if (!text) throw new Error("Neural Blank");
        return JSON.parse(text);
    });
}

export async function generateReflection(vault: SavedMatchup[]): Promise<{ axioms: NeuralAxiom[], levelUp: number, summary: string }> {
    return callWithRetry(async () => {
        const ai = getAI();
        const vaultStr = JSON.stringify(vault.slice(0, 20)); // Last 20 items

        const result = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: `Analyze these past betting outcomes: ${vaultStr}.
            Identify patterns where the model failed (LOSS) or succeeded (WIN).
            Extract 3-5 specific "Axioms" or rules to improve future accuracy.
            Calculate an "Evolution Level" increase (1-5) based on the insights found.`,
            config: {
                responseMimeType: 'application/json',
                responseSchema: reflectionSchema,
                thinkingConfig: { thinkingBudget: 1024 }
            }
        });

        const text = result.text;
        if (!text) throw new Error("Reflection Failed");

        const parsed = JSON.parse(text);
        return {
            axioms: parsed.axioms || [],
            levelUp: parsed.evolutionLevelChange || 0,
            summary: parsed.summary || "Analysis Complete."
        };
    });
}

