                <p className="text-[10px] text-zinc-500 leading-relaxed line-clamp-2 hover:line-clamp-none transition-all cursor-help border-l-2 border-amber-500/20 pl-2">
                    {prop.analysis}
                </p>
            </div>
        </div>
    );
});

