export async function getSchedule(sport: string, forceRefresh = false): Promise<Game[]> {
  const cacheKey = sport.toLowerCase();
  const cached = scheduleCache[cacheKey];

  if (!forceRefresh && cached && (Date.now() - cached.timestamp < CACHE_DURATION)) {
    return cached.data;
  }

  return callWithRetry(async () => {
    const ai = getAI();
    const result = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Find ALL currently scheduled or live ${sport} games for today and this week.
      IMPORTANT:
      1. If games are LIVE, include the current score (e.g., "24-17").
      2. If games are SCHEDULED, include the time.
      3. Include MONEYLINE, SPREAD, and TOTAL odds if available.
      4. Flag "isMustWin" as true if a team is facing elimination or fighting for a playoff spot.
      RETURN JSON ONLY.`,
      config: {
        responseMimeType: 'application/json',
        responseSchema: scheduleSchema,
        tools: [{ googleSearch: {} }]
      }
    });

    const text = result.text;
    if (!text) return [];

    const data = JSON.parse(text);
    const games = data.games || [];

    scheduleCache[cacheKey] = { data: games, timestamp: Date.now() };
    return games;
  });
}

